     4	// its own also takes local times and RFC 2822 dates.
     5	export function parseIso(text) {
     6	  if (typeof text !== 'string' || !ISO.test(text)) return null;
     7	  const ms = Date.parse(text);
     8	  return Number.isNaN(ms) ? null : ms;
     9	}

